package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.jlinalg.xwas.LdscHeritability;

/** Native unpartitioned observed-scale LDSC with explicit prepared-population choices. */
public final class LdscToolsCli {
    private static final String PROFILE="native-ldsc-hsq-cbiit302-v1";
    private static final String SCOPE="Native Java unpartitioned observed-scale LDSC Hsq: explicit free/fixed intercept or two-step intercept estimation, two IRWLS updates and block jackknife with frozen final stage weights. All declared rows contribute to the final slope. The cutoff selects only the two-step intercept population. Weight-feedback h2 is clamped to [0,1]; final estimates are retained unchanged, including negative/out-of-range estimates. Prepared rows must already be QC-filtered, aligned to their LD reference and genome-ordered. No allele harmonization, sample-size inference, LD-score computation, munging, ancestry matching, outlier removal, liability conversion, genetic correlation or partitioned model is inferred. Selected reference: unchanged CBIIT/ldsc3.0.2 numerical core commit6c673952cee74bd5c57aef1555a03b1c015399a0; historical edition and whole-paper parity remain separate. No Python runtime needed.";
    private static final String ACTION="Require exit0, COMPLETED.json and analysis.json result_admitted=true. SKIP3 means dependent analysis skipped for unavailable/forbidden input or an unsupported requested analysis. Supply permitted accessible prepared inputs or a separately qualified method and retry NEW output. FAIL2 means no result admitted: retain inputs and partial output, read FAILURE.txt/WARNINGS.md, correct the named complete-input, design, block-population or numeric-capacity issue and retry NEW output. Never remove failed blocks, replace nonfinite values, truncate rows or clamp final estimates to force success. For deployment or paper attribution, establish the exact author inputs, QC/reference population, settings and software edition separately.";
    static final int MAX_BYTES=64<<20;
    private record Input(List<String> variants,double[] chi,double[] ld,double[] wld,double[] n,boolean bom) { }
    private LdscToolsCli() { }
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    public static int run(String[] args,PrintStream output,PrintStream error) {
        Path owned=null;
        try {
            if(args.length>0&&args[0].equals("rg"))return LdscRgCli.run(Arrays.copyOfRange(args,1,args.length),output,error);
            if(args.length==0||args.length==1&&args[0].equals("--help")||args.length==2&&args[0].equals("h2")&&args[1].equals("--help")) {
                output.println("ldsc-tools rg --request UTF8_JSON\n  Native prepared two-trait Hsq/Gencov/RG with explicit allele alignment, three intercept choices and correlation-reportability policy. Use rg --help.\n");
                output.println("ldsc-tools h2 --request UTF8_JSON\nRequired request: schema_version=1,input (UTF-8 literal TSV),out NEW,reference_variants (positive finite M),n_blocks (2..10000),intercept (JSON number or string free),two_step (positive JSON number or null),data_provenance,row_order_declaration. Declare both intercept and two_step explicitly; a fixed intercept and two-step are mutually exclusive.\nInput header: variant<TAB>chi_square<TAB>ld_score<TAB>weight_ld_score<TAB>n. Unique literal variant IDs; complete finite rows; chi-square>=0,N>0. Signed LD estimates are retained as regressors. Only weighting floors LD/weight-LD below1, following the selected original method. Paths resolve against the request.\nWhole-input refusal limits: 64MiB,2million rows; no population truncation. Two-step intercept rows must support every declared delete fit. Outputs preserve exact request/input, estimates/NA diagnostics, complete block deletes/covariance, row weights/cutoff membership, weight-update trace, warnings and checksummed completion.\n"+SCOPE+"\n"+ACTION);output.flush();return output.checkError()?2:0;
            }
            if(Set.of("partitioned","ld-score").contains(args[0])) {
                error.println("SKIP3: DEPENDENT ANALYSIS SKIPPED. This prepared univariate Hsq command does not implement requested analysis "+args[0]+".\nREQUIRED ACTION: "+ACTION);error.flush();return 3;
            }
            require(args.length==3&&args[0].equals("h2")&&args[1].equals("--request"),"Use ldsc-tools h2 --request JSON or --help");
            Path request=regular(Path.of(args[2]));var requestPin=NextflowFiles.pin(request,1048576,()->{});byte[] requestBytes=NextflowFiles.bytes(request,1048576);require(requestPin.equals(pin(requestBytes)),"Request changed during capture");
            Map<?,?> m=NextflowFiles.object(NextflowParameters.parse(NextflowFiles.utf8(requestBytes),1048576,100000));
            NextflowFiles.keys(m,"schema_version","input","out","reference_variants","n_blocks","intercept","two_step","data_provenance","row_order_declaration");NextflowFiles.integer(m.get("schema_version"),1,1);
            String provenance=label(NextflowFiles.text(m.get("data_provenance"))),order=label(NextflowFiles.text(m.get("row_order_declaration")));
            double reference=number(m.get("reference_variants"));int blocks=(int)NextflowFiles.integer(m.get("n_blocks"),2,LdscHeritability.MAXIMUM_BLOCKS);
            Object intercept=m.get("intercept");Double fixed=intercept instanceof String text&&text.equals("free")?null:number(intercept);
            Double cutoff=m.get("two_step")==null?null:number(m.get("two_step"));
            Path input=regular(resolve(request.getParent(),m.get("input")));Path dest=destination(resolve(request.getParent(),m.get("out")),List.of(request,input));Files.createDirectories(dest.getParent());Files.createDirectory(dest);owned=dest;
            write(owned.resolve("WARNINGS.md"),"# Scope, warnings and required actions\n\n"+SCOPE+"\n\n"+ACTION+"\n\nBlock jackknife uses consecutive rows: input order and the declared reference/QC population determine inference. A valid numerical fit does not establish ancestry matching, biological adequacy or independent loci. Standard errors use the selected original fixed-stage-weight jackknife; IRWLS is not rerun for each delete. Undefined original diagnostics remain NA.\n");
            Files.write(owned.resolve("source-request.json"),requestBytes,StandardOpenOption.CREATE_NEW);var inputPin=NextflowFiles.pin(input,MAX_BYTES,()->{});byte[] inputBytes=NextflowFiles.bytes(input,MAX_BYTES);require(inputPin.equals(pin(inputBytes)),"Input changed during complete capture");Files.write(owned.resolve("source-input.tsv"),inputBytes,StandardOpenOption.CREATE_NEW);
            Input data=read(inputBytes);var result=LdscHeritability.fit(data.chi(),data.ld(),data.wld(),data.n(),reference,blocks,fixed,cutoff);
            var diagnostics=new LinkedHashMap<String,Object>();diagnostics.put("h2",result.h2());diagnostics.put("h2_se",result.h2StandardError());diagnostics.put("coefficient",result.coefficient());diagnostics.put("coefficient_se",result.coefficientStandardError());diagnostics.put("intercept",result.intercept());diagnostics.put("intercept_se",result.interceptStandardError());diagnostics.put("mean_chi_square",result.meanChiSquare());diagnostics.put("lambda_gc",result.lambdaGc());diagnostics.put("ratio",result.ratio());diagnostics.put("ratio_se",result.ratioStandardError());
            var table=new StringBuilder("metric\tvalue\n");for(var entry:diagnostics.entrySet())table.append(entry.getKey()).append('\t').append(entry.getValue()==null?"NA":entry.getValue()).append('\n');write(owned.resolve("estimates.tsv"),table.toString());
            var deletes=new StringBuilder("block\th2_delete\tintercept_delete\n");double[][] values=result.deleteValues();for(int i=0;i<blocks;i++)deletes.append(i).append('\t').append(values[i][0]).append('\t').append(values[i][1]).append('\n');write(owned.resolve("delete-values.tsv"),deletes.toString());
            var covariance=new StringBuilder("first\tsecond\tcovariance\n");double[][] cov=result.covariance();for(int i=0;i<2;i++)for(int j=0;j<2;j++)covariance.append(i==0?"h2":"intercept").append('\t').append(j==0?"h2":"intercept").append('\t').append(cov[i][j]).append('\n');write(owned.resolve("covariance.tsv"),covariance.toString());
            double[] weights=result.finalWeights();var rows=new StringBuilder("row_index\tvariant\tstep1_selected\tfinal_precision_weight\n");int lowLd=0,lowWld=0;
            for(int i=0;i<weights.length;i++){rows.append(i).append('\t').append('"').append(data.variants().get(i).replace("\"","\"\"")).append('"').append('\t').append(cutoff==null||data.chi()[i]<cutoff).append('\t').append(weights[i]).append('\n');if(data.ld()[i]<1)lowLd++;if(data.wld()[i]<1)lowWld++;}write(owned.resolve("row-audit.tsv"),rows.toString());
            var boundaries=new StringBuilder("boundary\tfull_row_position\tstep1_row_position\n");int[] full=result.fullSeparators(),first=result.step1Separators();for(int i=0;i<full.length;i++)boundaries.append(i).append('\t').append(full[i]).append('\t').append(first.length==0?"NA":first[i]).append('\n');write(owned.resolve("block-boundaries.tsv"),boundaries.toString());
            var updateTable=new StringBuilder("stage\tupdate\testimated_h2\tweighting_h2\tintercept\n");boolean clamped=false;for(var w:result.weightUpdates()){updateTable.append(w.stage()).append('\t').append(w.update()).append('\t').append(w.estimatedH2()).append('\t').append(w.weightingH2()).append('\t').append(w.intercept()).append('\n');clamped|=w.estimatedH2()!=w.weightingH2();}write(owned.resolve("weight-updates.tsv"),updateTable.toString());
            var observed=new ArrayList<String>();if(result.h2()<0||result.h2()>1)observed.add("Final observed h2 lies outside[0,1] and is retained unchanged; inspect model/reference/QC adequacy before interpretation.");if(clamped)observed.add("Original weight feedback clamped one or more h2 estimates to[0,1]; final estimates were not clamped. Read weight-updates.tsv.");if(lowLd>0||lowWld>0)observed.add("Original weighting floors LD/weight-LD below1. Complete original signed regressor values remain unchanged. Raw rows below1: LD="+lowLd+",weight-LD="+lowWld+"; first-stage two-step updates use the source N-scaled LD column.");if(result.ratio()==null)observed.add("Ratio/SE are NA for a fixed intercept or mean chi-square<=1; this is an undefined/not-estimated diagnostic, not zero.");if(fixed!=null)observed.add("Intercept SE is NA because the intercept was fixed. Its zero covariance entries describe a fixed parameter, not a fitted SE.");
            if(!observed.isEmpty())Files.writeString(owned.resolve("WARNINGS.md"),"\n## Observed warnings\n\n"+String.join("\n\n",observed)+"\n",StandardCharsets.UTF_8,StandardOpenOption.APPEND);
            var report=new LinkedHashMap<String,Object>();report.put("profile",PROFILE);report.put("result_admitted",true);report.put("rows",result.rows());report.put("blocks",blocks);report.put("reference_variants",reference);report.put("mean_sample_size",result.meanSampleSize());report.put("intercept_setting",intercept);report.put("two_step_cutoff",cutoff);report.put("step1_rows",result.step1Rows());report.put("data_provenance",provenance);report.put("row_order_declaration",order);report.put("utf8_bom_present",data.bom());report.put("diagnostics",diagnostics);report.put("observed_warnings",observed);report.put("whole_vendor_tool_qualified",false);report.put("whole_goal_complete",false);
            require(!Thread.currentThread().isInterrupted(),"LDSC analysis interrupted; no result admitted");require(inputPin.equals(NextflowFiles.pin(input,MAX_BYTES,()->{}))&&inputPin.equals(NextflowFiles.pin(owned.resolve("source-input.tsv"),MAX_BYTES,()->{})),"Original/captured input changed");require(requestPin.equals(NextflowFiles.pin(request,1048576,()->{}))&&requestPin.equals(NextflowFiles.pin(owned.resolve("source-request.json"),1048576,()->{})),"Request changed during analysis");NextflowFiles.writeJson(owned.resolve("analysis.json"),report);
            var manifest=new TreeMap<String,Object>();try(var files=Files.walk(owned)){for(Path p:files.filter(Files::isRegularFile).sorted().toList())manifest.put(owned.relativize(p).toString().replace('\\','/'),NextflowFiles.pin(p,256L<<20,()->{}));}NextflowFiles.writeJson(owned.resolve("manifest.json"),manifest);
            output.println("PASS native LDSC Hsq: "+result.rows()+" rows,"+blocks+" blocks. "+(observed.isEmpty()?"":"OBSERVED WARNINGS="+observed.size()+". ")+"READ "+owned.resolve("WARNINGS.md"));output.flush();error.flush();require(!output.checkError()&&!error.checkError(),"Console recording failed; no result admitted");NextflowFiles.writeJson(owned.resolve("COMPLETED.json"),Map.of("status","PASS_NATIVE_LDSC_HSQ","profile",PROFILE,"manifest",NextflowFiles.pin(owned.resolve("manifest.json"),1048576,()->{})));return 0;
        } catch(Exception e){return failed(owned,e,error);}
          catch(OutOfMemoryError e){return failed(owned,new IOException("Heap exhausted; preserve inputs and retry NEW output with sufficient resources; no partial result",e),error);}
    }
    private static Input read(byte[] raw)throws IOException {
        String text=NextflowFiles.utf8(raw);boolean bom=text.startsWith("\ufeff");if(bom)text=text.substring(1);var ids=new ArrayList<String>();var seen=new HashSet<String>();var values=new ArrayList<double[]>();
        try(var lines=text.lines()){var it=lines.iterator();require(it.hasNext()&&it.next().equals("variant\tchi_square\tld_score\tweight_ld_score\tn"),"Require exact variant/chi_square/ld_score/weight_ld_score/n TSV header");while(it.hasNext()){String[] row=it.next().split("\t",-1);require(row.length==5,"Every row requires5 complete literal fields; blank rows are not removed");String id=label(row[0]);require(seen.add(id),"Duplicate variant ID; no inferred join or deduplication");ids.add(id);require(ids.size()<=LdscHeritability.MAXIMUM_ROWS,"Complete input exceeds two million rows");values.add(new double[]{decimal(row[1]),decimal(row[2]),decimal(row[3]),decimal(row[4])});}}
        double[][] columns=new double[4][values.size()];for(int i=0;i<values.size();i++)for(int j=0;j<4;j++)columns[j][i]=values.get(i)[j];return new Input(List.copyOf(ids),columns[0],columns[1],columns[2],columns[3],bom);
    }
    private static int failed(Path owned,Exception cause,PrintStream error) {
        int code=cause instanceof NoSuchFileException||cause instanceof AccessDeniedException||cause instanceof SecurityException?3:2;String message=(code==3?"SKIP3: DEPENDENT ANALYSIS SKIPPED. ":"FAIL2: NO LDSC RESULT ADMITTED. ")+cause+"\nREQUIRED ACTION: "+ACTION+"\n";
        if(owned!=null)try{Files.deleteIfExists(owned.resolve("COMPLETED.json"));if(Files.exists(owned.resolve("analysis.json")))Files.move(owned.resolve("analysis.json"),owned.resolve("unadmitted-analysis.json"));NextflowFiles.writeJson(owned.resolve("analysis.json"),Map.of("result_admitted",false,"status",code==3?"SKIP3_DEPENDENT_ANALYSIS_SKIPPED":"FAIL2_NO_RESULT_ADMITTED","cause",cause.toString(),"required_action",ACTION));write(owned.resolve("FAILURE.txt"),message);}catch(IOException recording){message+="Failure recording also failed: "+recording+"\n";}
        error.print(message);error.flush();return code;
    }
    static double decimal(String x)throws IOException{require(x.length()<=256&&x.matches("[+-]?(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)(?:[eE][+-]?[0-9]+)?"),"Complete finite decimal required; no row removal/repair");double v=Double.parseDouble(x);require(Double.isFinite(v),"Nonfinite value");return v;}
    static double number(Object x)throws IOException{if(x instanceof NextflowParameters.NumberToken n)return decimal(n.text());if(x instanceof Number n){double value=n.doubleValue();require(Double.isFinite(value),"Finite number required");return value;}throw new IOException("JSON number required");}
    static String label(String x)throws IOException{require(!x.isBlank()&&x.length()<=32768&&x.chars().noneMatch(c->c<32||c==127),"Literal nonblank labels/paths/declarations without control characters required");return x;}
    static Path resolve(Path parent,Object x)throws IOException{Path p=Path.of(label(NextflowFiles.text(x)));return(p.isAbsolute()?p:parent.resolve(p)).toAbsolutePath().normalize();}
    static Path regular(Path p)throws IOException{p=p.toAbsolutePath().normalize();if(!Files.exists(p,LinkOption.NOFOLLOW_LINKS))throw new NoSuchFileException(p.toString());require(Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS),"Regular unlinked input required");return p.toRealPath();}
    static Path destination(Path absolute,List<Path> protectedInputs)throws IOException{require(!Files.exists(absolute,LinkOption.NOFOLLOW_LINKS),"Output exists; preserve it and select NEW output");Path parent=absolute.getParent();require(parent!=null,"Output needs a parent");while(!Files.exists(parent,LinkOption.NOFOLLOW_LINKS))parent=parent.getParent();Path resolved=parent.toRealPath().resolve(parent.relativize(absolute)).normalize();for(Path input:protectedInputs)require(!input.startsWith(resolved)&&!resolved.startsWith(input),"Output overlaps protected input");return resolved;}
    static NextflowFiles.Pin pin(byte[] raw){return new NextflowFiles.Pin(raw.length,NextflowFiles.sha(raw));}
    static void write(Path p,String text)throws IOException{Files.writeString(p,text,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);}
    static void require(boolean value,String message)throws IOException{if(!value)throw new IOException(message);}
}
